def marshal_test_all_types(
    msg: Any,
    *,
    deterministic: bool = False,
    self_describing: bool = False,
) -> bytes:
    dst = bytearray()
    if self_describing:
        dst.extend(_FIELD0_TEST_ALL_TYPES)
    try:
        _encode_test_all_types(dst, msg, deterministic)
    except UnicodeEncodeError as exc:
        raise OmniBufEncodeError(str(exc)) from exc
    return bytes(dst)

def _decode_test_all_types(
    data: Buffer,
    out: TestAllTypes | None = None,
    depth: int = 0,
    merge: bool = False,
) -> TestAllTypes:
    if depth > MAX_NESTING_DEPTH:
        raise OmniBufDecodeError("omnibuf: nesting depth exceeds limit")
    if out is None:
        out = TestAllTypes()
    elif not merge:
        out.f1_uint32 = 0
        out.f2_uint64 = 0
        out.f3_sint32 = 0
        out.f4_sint64 = 0
        out.f5_bool = False
        out.f6_string = ""
        out.f7_bytes = b""
        out.f8_sub_msg = None
        out.f9_string_arr.clear()
        out.f10_uint32_arr.clear()
        out.f11_sub_msg_arr.clear()
        out.f12_map_str_uint.clear()
        out.f13_float32 = 0.0
        out.f14_float64 = 0.0
        out.f15_fixed32 = 0
        out.f16_fixed64 = 0
        out.f20_overflow_str = ""
